  setCheckoutError(e.message==="destination_not_found"?"Endereço não localizado. Confira os dados ou use Minha localização.":e.message==="origin_not_found"?"O endereço do restaurante não foi localizado.":e.message==="outside_delivery_distance"||e.message==="outside_delivery_area"?"O endereço está fora da área de entrega.":"Não foi possível calcular o frete: "+e.message)
