async function savePendingBairroFees(){if(!pendingBairroFees.length||saving)return;if(!selectedCity.includes("|")){setError("Selecione uma cidade.");return}const invalid=pendingBairroFees.find(([,v])=>!Number.isFinite(cents(v))||cents(v)<0);if(invalid){setError("Confira os valores informados antes de salvar.");return}setSaving(true);setError("");const [city,stateCode]=selectedCity.split("|");const failed=[];for(const [key,value] of pendingBairroFees){const existing=scopedAreas.find(a=>normBairro(a.neighborhood)===key);const item=cityNeighborhoods.find(x=>normBairro(x.name)===key);const name=existing?.neighborhood||item?.name;if(!name){failed.push(key);continue}const data={neighborhood:name,neighborhoodKey:key,city,state:stateCode,feeCents:cents(value),active:true,source:"MANUAL",updatedAt:serverTimestamp()};try{if(existing)await updateDoc(doc(db,"restaurants",rid,"deliveryAreas",existing.id),data);else await addDoc(collection(db,"restaurants",rid,"deliveryAreas"),{...data,minimumOrderCents:0,estimatedMinutes:40,createdAt:serverTimestamp()});setBairroFees(v=>{if(v[key]!==value)return v;const copy={...v};delete copy[key];return copy})}catch{failed.push(name)}}setSaving(false);if(failed.length)setError("Não foi possível salvar: "+failed.join(", ")+". Os demais valores foram gravados.");}
